/*
 * Interface between code generated by the WebAssembly TCG backend and
 * the C runtime in tcg/wasm.c.
 */

#ifndef TCG_WASM_RUNTIME_H
#define TCG_WASM_RUNTIME_H

#include "tcg/tcg.h"

/*
 * Value returned by a translation block function to ask tcg_wasm_tb_exec()
 * to continue with the block whose code pointer is in TCGWasmFrame.next.
 * exit_tb never returns it: its value is 0 or a TB pointer plus exit index.
 */
#define TCG_WASM_EXIT_CHAIN  1

/* Placed at tb->tc.ptr, in front of the module bytes. */
typedef struct TCGWasmTBHeader {
    /* Index in the function table, valid when owner is this thread. */
    uint32_t func;
    /* Token of the thread that instantiated func, or 0. */
    uint32_t owner;
    /* Location of the WebAssembly module, relative to the header. */
    uint32_t module_ofs;
    uint32_t module_len;
} TCGWasmTBHeader;

/*
 * The frame that tcg_wasm_tb_exec() passes as TCG_REG_CALL_STACK.  It
 * starts with the area described by tcg_set_frame(), followed by state
 * shared with the generated code.
 */
typedef struct TCGWasmFrame {
    uint64_t stack[(TCG_STATIC_CALL_ARGS_SIZE + TCG_STATIC_FRAME_SIZE)
                   / sizeof(uint64_t)];
    /* Code address of the current helper call, read by GETPC(). */
    uintptr_t ra;
    /* Code pointer of the next block, with TCG_WASM_EXIT_CHAIN. */
    uintptr_t next;
    /*
     * Non-zero while an Asyncify unwind is in progress through this
     * frame: the segment of the generated function to resume.
     */
    uint32_t resume;
    /* Register locals saved while unwinding. */
    uint64_t save[TCG_TARGET_NB_REGS];
} TCGWasmFrame;

uintptr_t tcg_wasm_tb_exec(CPUArchState *env, const void *tb_ptr);
bool tcg_wasm_memory_is_shared(void);

#endif /* TCG_WASM_RUNTIME_H */
